//go:build arm64

package floats

// Add32, Sub32, Mul32, Div32 and Sqrt32 kernels (binop32.go), generated by
// go-asmgen (binop32_arm64_gen.go) into binop32_arm64.s. NEON is the ARMv8-A
// baseline: no gate. The callers pass every slice already sliced to the common
// length. No kernel keeps a pointer: every stub is go:noescape.
//
//go:noescape
func add32NEON(dst, a, b []float32)

//go:noescape
func sub32NEON(dst, a, b []float32)

//go:noescape
func mul32NEON(dst, a, b []float32)

//go:noescape
func div32NEON(dst, a, b []float32)

//go:noescape
func sqrt32NEON(dst, src []float32)

func add32(dst, a, b []float32) { add32NEON(dst, a, b) }
func sub32(dst, a, b []float32) { sub32NEON(dst, a, b) }
func mul32(dst, a, b []float32) { mul32NEON(dst, a, b) }
func div32(dst, a, b []float32) { div32NEON(dst, a, b) }
func sqrt32(dst, src []float32) { sqrt32NEON(dst, src) }
